let start = key.slice(0,1);
let type;
let f = true;

if(cache.get("bilibili_search_2")=="1"){
	cache.delete("bilibili_search_2");
	f = false;
	start = String(cache.get("bilibili_search"));
	key = start + key;
}

switch(start){
	case "@":
	    type = "bili_user";
	    break;
	case "#":
	case "＃":
	    type = "article"
	    break;
	case "%":
	    type = "video"
	    break
	case "&":
	    type = "live"
	    break;
	case "*":
	    type = "media_bangumi";
	    break;
	 case "?":
	 case "？":
	     type = "media_ft"
	     break
	}

if(type ||(String(source.get("bilibili_page"))&&page>1)){
	key = key.substring(1);
	if(f)java.put("searchtype",start);
	if(f&&!type)java.put("searchtype","");
queryJson = {
        __refresh__: true,
        _extra: '',
        context: '',
        page: page,
        page_size: 30,
        order: getSearchOrder(),
        duration: '',
        from_source: '',
        from_spmid: 333.337,
        platform: 'pc',
        highlight: 1,
        single_column: 0,
        keyword: key,
        search_type: type,
        preload: true,
        com2co: true
    }

    if(page == 1){
    	    source.put("bilibili_page",JSON.stringify(queryJson));
    	}else{
    		queryJson =JSON.parse(String(source.get("bilibili_page")))
