            style:style(field.type === 'toggle' ? 'right' : 'flex_end')});
    }
    function back() { button('返回主菜单','fqUiPage("main")'); }
    if (page === 'account') {
        button('账号状态\n'+fqAccountState(src).label,'fqUiAccountCheck()');
        button('网页登录','fqUiAccountLogin()');
        button('检查登录状态','fqUiAccountCheck()');
        button('清除本机登录','fqUiAccountClear()');
        button('登录说明','fqUiHelp("account")');
        back();
    } else if (page === 'reading') {
        control('bubbleMode'); control('showEmpty');
        button('刷新段评数','fqUiRefreshCounts()');
        button('使用说明','fqUiHelp("reading")');
        back();
    } else if (page === 'explore') {
        control('exploreMode');
        button('刷新发现','fqUiRefreshExplore()');
        button('布局说明','fqUiHelp("explore")');
        back();
    } else if (page === 'help') {
        button('兼容说明','fqUiHelp("compatibility")');
        button('恢复默认','fqUiReset()');
        back();
    } else {
        var accountState = fqAccountState(src);
        button('番茄账号\n' + accountState.label,'fqUiPage("account")');
        button('阅读设置\n' + bubbleTitle,'fqUiPage("reading")');
        button('发现设置\n' + (settings.exploreMode === 'rich' ? '书城导航' : '经典分类'),'fqUiPage("explore")');
        button('帮助与维护\n说明与恢复','fqUiPage("help")');
        for (var i = 0; i < rows.length; i++) {
            rows[i].style.layout_flexBasisPercent=0.48;
            rows[i].style.layout_flexGrow=1;
            rows[i].style.layout_wrapBefore=i % 2 === 0;
        }
    }
    return JSON.stringify(rows);
}

function fqSettingsToast(host, message) {
    if (host && typeof host.toast === 'function') host.toast(message);
}

function fqSettingsHelp(host, topic) {
