function fqRebuildLogin(host) {
    try { if (host && typeof host.reLoginView === 'function') { host.reLoginView(false); return true; } } catch (ignore) {}
    try { if (host && typeof host.refreshExplore === 'function') { host.refreshExplore(); return true; } } catch (ignore) {}
    return false;
}

function fqSyncSettingsForm(src, host) {
    try {
        if (host && typeof host.upLoginData === 'function') { host.upLoginData(fqSettingsFormValues(fqSettings(src))); return true; }
    } catch (ignore) {}
    return false;
}

function fqRefreshReadingDisplay(host) {
    try { if (host && typeof host.refreshContent === 'function') host.refreshContent(); } catch (ignore) {}
}

function fqClearDiscoverySettings(src) {
    if (!src || typeof src.refreshExplore !== 'function') return false;
    src.refreshExplore(); return true;
}

function fqSettingsPage(src, host, page) {
    var values = fqStoredSettings(src); values.settingsMenu = fqSettingsMenu(page); src.putVariable(JSON.stringify(values));
    // Also updates values for fields not mounted on the current page, so old
    // persisted native form state cannot override the source's current settings.
    fqSyncSettingsForm(src,host);
    if (!fqRebuildLogin(host)) fqSettingsToast(host,'请重新打开设置');
}

function fqCommitSetting(src, host, key, value) {
    if (key === 'bubbleMode' && value === 'max') value='outline';
    if (key === 'chapterDiscussion') throw new Error('番茄：章末评论已移除，请重新打开设置');
    if (!Object.prototype.hasOwnProperty.call(FQ_SETTINGS_FIELDS,key) || FQ_SETTINGS_FIELDS[key].values.indexOf(value) < 0) throw new Error('番茄：无效的设置选项');
    var values = fqStoredSettings(src), old = fqSettings(src)[key];
    if (old === value && (key !== 'exploreMode' || (values.exploreLayoutRevision === FQ_EXPLORE_LAYOUT_REVISION && values.exploreMode === value))) return false;
    // Reload source state for each event and write only the changed field.
    // Other controls in a native result Map may be stale or from another page.
    values[key] = value;
    if (key === 'exploreMode') values.exploreLayoutRevision = FQ_EXPLORE_LAYOUT_REVISION;
    src.putVariable(JSON.stringify(values));
    if (key === 'exploreMode') {
        var message = '已保存；返回发现页后长按书源名刷新';
        try { fqClearDiscoverySettings(src); } catch (error) { message = '布局已保存，请返回发现页刷新'; }
        fqSettingsToast(host,message);
    } else {
        fqRefreshReadingDisplay(host); fqSettingsToast(host,'已保存；刷新本章后应用');
    }
    return true;
}

function fqApplySettingsForm(src, form, host, key) {
    if (key === 'chapterDiscussion') throw new Error('番茄：章末评论已移除，请重新打开设置');
    if (!Object.prototype.hasOwnProperty.call(FQ_SETTINGS_FIELDS,key)) throw new Error('番茄：无效的设置项');
    var field = FQ_SETTINGS_FIELDS[key];
    var raw = form && typeof form.get === 'function' ? form.get(field.name) : form && form[field.name];
    if (key === 'bubbleMode' && (raw === null || typeof raw === 'undefined')) {
        raw = form && typeof form.get === 'function' ? form.get('fqV6Bubble') : form && form.fqV6Bubble;
        if (fqString(raw) === 'Max 内置') raw='通用线框';
    }
    // An already-mounted pre-import control may still submit the old field.
    // Only a genuinely absent new field permits this action-time fallback.
    if (key === 'exploreMode' && (raw === null || typeof raw === 'undefined')) {
        raw = form && typeof form.get === 'function' ? form.get('fqV6Explore') : form && form.fqV6Explore;
    }
    var index = field.chars.indexOf(fqString(raw));
    if (index < 0) throw new Error('番茄：设置值无效，请重新打开设置');
    // Native select skips its first callback. An unchanged callback is also a
    // no-op here, protecting against client variants and programmatic resets.
    return fqCommitSetting(src,host,key,field.values[index]);
}

// Compatibility entry for earlier saved buttons; keep the user on this page.
function fqSelectSetting(src, host, key, value) {
    var changed = fqCommitSetting(src,host,key,value);
    fqSyncSettingsForm(src,host); fqRebuildLogin(host);
    return changed;
}

function fqResetUiSettings(src, host) {
    var values = fqStoredSettings(src), old = fqSettings(src);
    values.bubbleMode='outline'; values.showEmpty=false; values.exploreMode='compact';
    delete values.chapterDiscussion;
    values.exploreLayoutRevision=FQ_EXPLORE_LAYOUT_REVISION;
    values.settingsMenu=fqSettingsMenu(values.settingsMenu); src.putVariable(JSON.stringify(values));
    if (old.exploreMode !== 'compact') { try { fqClearDiscoverySettings(src); } catch (ignore) {} }
    // Update native form Map before rebuilding; merely changing default leaves
    // old select values and a toggle's captured state in the existing view.
    fqSyncSettingsForm(src,host); fqRebuildLogin(host); fqRefreshReadingDisplay(host);
    fqSettingsToast(host,'已恢复默认；已有正文与发现页请刷新');
}

function fqRefreshExploreMenu(src, host) {
    try { fqClearDiscoverySettings(src); fqSettingsToast(host,'返回发现页后长按书源名刷新界面'); }
    catch (error) { fqSettingsToast(host,'请返回发现页重试刷新'); }
}

// Retain old form actions without resetting fields absent from that form.
function fqSaveSettings(src, form, host) {
    function get(key) { return fqString(form && typeof form.get === 'function' ? form.get(key) : form && form[key]); }
    var values=fqStoredSettings(src), old=fqSettings(src), mode=FQ_BUBBLE_MODES[get('气泡样式')];
    if (mode) values.bubbleMode=mode;
    if (get('显示无评论段落')) values.showEmpty=get('显示无评论段落') === '显示';
    delete values.chapterDiscussion;
    if (get('发现布局')) {
        values.exploreMode=get('发现布局') === '经典分类' ? 'compact' : 'rich';
        values.exploreLayoutRevision=FQ_EXPLORE_LAYOUT_REVISION;
    }
    values.settingsMenu=fqSettingsMenu(values.settingsMenu); src.putVariable(JSON.stringify(values));
    try { if (old.exploreMode !== fqSettings(src).exploreMode) fqClearDiscoverySettings(src); } catch (ignore) {}
    fqSyncSettingsForm(src,host); fqRefreshReadingDisplay(host); fqRebuildLogin(host); fqSettingsToast(host,'已保存；刷新本章后应用');
}

function fqRefreshCommentCounts(src, host) {
    var values=fqStoredSettings(src), old=fqSettings(src);
    values.cacheEpoch=Math.max(Date.now(),old.cacheEpoch+1); src.putVariable(JSON.stringify(values));
    fqRefreshReadingDisplay(host); fqSettingsToast(host,'请刷新本章，重新获取段评数量');
}

function fqCachedParagraphStats(bookId, chapterId, host, src, cacheHost, settings) {
    if (!cacheHost) return fqLoadParagraphStats(bookId,chapterId,host);
    var key='fq-v3:counts:' + (src && typeof src.getKey === 'function' ? fqString(src.getKey()) : FQ_ORIGIN) + ':' + fqId(bookId) + ':' + fqId(chapterId) + ':' + settings.cacheEpoch;
    try {
        var saved=cacheHost.get(key);
        if (saved) { var entry=fqParseJson(saved,false), age=Date.now()-Number(entry.time); if (age >= 0 && age < 300000 && entry.data) return entry.data; }
    } catch (ignore) {}
    var stats=fqLoadParagraphStats(bookId,chapterId,host);
    try { cacheHost.put(key,JSON.stringify({time:Date.now(),data:stats}),300); } catch (ignore) {}
    return stats;
}

/* Official website account lifecycle. No token is stored in source settings,
 * printed, or sent to a third-party service. UI rendering is entirely local. */
var FQ_ACCOUNT_SITE = FQ_ORIGIN+'/';
var FQ_ACCOUNT_DOMAIN = FQ_ORIGIN.slice(8);
var FQ_ACCOUNT_INFO = FQ_ORIGIN+'/api/user/info/v2';

function fqAccountValues(src) {
    var raw = src && typeof src.getVariable === 'function' ? src.getVariable() : '';
    var values = raw == null || !String(raw).trim() ? {} : fqParseJson(String(raw),false);
    if (!values || typeof values !== 'object' || Array.isArray(values)) throw new Error('账号设置无法读取');
    return values;
}

function fqAccountDisplay(status, name) {
    name = typeof name === 'string' ? name.replace(/[\u0000-\u001f\u007f]/g,'').trim().slice(0,80) : '';
    if (status !== 'signed-in' && status !== 'signed-out') status = 'unknown';
    if (status === 'signed-in' && !name) status = 'unknown';
    if (status !== 'signed-in') name = '';
    return {status:status,name:name,label:status === 'signed-in' ? '上次已验证 · ' + name : status === 'signed-out' ? '未登录' : '状态待检查'};
}

function fqAccountState(src) {
    try { var account = fqAccountValues(src).account || {}; return fqAccountDisplay(account.status,account.name); }
    catch (ignore) { return fqAccountDisplay('unknown',''); }
}

function fqAccountFinish(src, host, status, name, message) {
    var state = fqAccountDisplay(status,name);
    try {
        var values = fqAccountValues(src);
        values.account = {status:state.status,name:state.name};
        src.putVariable(JSON.stringify(values));
    } catch (ignore) { message += '；本地状态未保存，请重新打开设置'; }
    fqSettingsToast(host,message); fqRebuildLogin(host);
    return state;
}

function fqAccountSession(cookieHost) {
    if (!cookieHost || typeof cookieHost.getKey !== 'function') throw new Error('客户端未提供站点会话接口');
    var raw = cookieHost.getKey(FQ_ACCOUNT_DOMAIN,'sessionid');
    var value = raw == null ? '' : String(raw).trim();
    if (!value || value === 'null' || value === 'undefined') return '';
    // A session cookie is an opaque value, never a header or an executable rule.
    if (!/^[A-Za-z0-9._~%+=\/-]{1,2048}$/.test(value)) throw new Error('站点会话格式异常');
    return value;
}


function fqAccountCookieMap(text) {
    var out={},parts=String(text||'').split(';');
    for(var i=0;i<parts.length;i++) {
        var part=parts[i].trim(),at=part.indexOf('=');
        if(at<1)continue;
        var key=part.slice(0,at).trim(),value=part.slice(at+1).trim();
        if(!/^[A-Za-z0-9_.-]+$/.test(key)||/[\x00-\x1f\x7f]/.test(value))throw new Error('官网会话格式异常');
        out[key]=value;
    }
    return out;
}

function fqAccountCookieText(cookieHost) {
    if(!cookieHost||typeof cookieHost.getCookie!=='function') {
        var session=fqAccountSession(cookieHost);
        return session?'sessionid='+session:'';
    }
    var raw=String(cookieHost.getCookie(FQ_ACCOUNT_SITE)||'');
    if(/[\r\n\x00]/.test(raw)||raw.length>32768)throw new Error('官网会话格式异常');
    var values=fqAccountCookieMap(raw),parts=[];
    for(var key in values)if(Object.prototype.hasOwnProperty.call(values,key))parts.push(key+'='+values[key]);
    return parts.join('; ');
}

function fqAccountAuthSignature(text) {
    var values=fqAccountCookieMap(text),keys=['sessionid','sessionid_ss','sid_tt','sid_guard'],parts=[];
    for(var i=0;i<keys.length;i++)if(values[keys[i]])parts.push(keys[i]+'='+values[keys[i]]);
    return parts.join('; ');
}

function fqAccountCache(store) {
    return store||(typeof cache==='undefined'?null:cache);
}

function fqAccountSync(cookieHost,store,required) {
    if(!cookieHost||typeof cookieHost.getCookie!=='function'||typeof cookieHost.setCookie!=='function') {
        if(required)throw new Error('客户端无法同步官网会话');
        return false;
    }
    store=fqAccountCache(store);
    if(typeof cookieHost.captureFromWebView==='function') {
        // NG's public method captures a source-scoped store. Its removeCookie
        // does not clear WebView. Never use the global cache key in this branch.
        var prior=fqAccountCookieText(cookieHost),changed=false;
        try {
            if(typeof cookieHost.removeCookie!=='function')throw new Error('客户端无法同步官网会话');
            cookieHost.removeCookie(FQ_ACCOUNT_SITE);changed=true;
            if(fqAccountCookieText(cookieHost))throw new Error('旧会话未清除');
            cookieHost.captureFromWebView(FQ_ACCOUNT_SITE,FQ_ACCOUNT_SITE);
            if(!fqAccountAuthSignature(fqAccountCookieText(cookieHost)))throw new Error('网页尚未提供登录会话');
            return true;
        } catch(ignore) {
            if(changed)try {
                cookieHost.removeCookie(FQ_ACCOUNT_SITE);
                if(prior)cookieHost.setCookie(FQ_ACCOUNT_SITE,prior);
                if(fqAccountCookieText(cookieHost)!==prior)throw new Error('恢复失败');
            }catch(restoreError){throw new Error('官网会话同步失败，原有记录未能恢复，请重新网页登录');}
            // A native capture was attempted and failed. Restoring the old
            // store protects it, but cannot prove it is the browser's current
            // account. A status check must not validate that old account next.
            throw new Error('未确认网页登录会话，请完成网页登录后重试');
        }
    }
    var webText;
    try {
        webText=String(Packages.android.webkit.CookieManager.getInstance().getCookie(FQ_ACCOUNT_SITE)||'');
    }catch(ignore){if(required)throw new Error('无法读取网页登录会话，请稍后检查登录状态');return false;}
    if(/[\r\n\x00]/.test(webText)||!fqAccountAuthSignature(webText)) {
        if(required)throw new Error('网页尚未提供登录会话，请完成网页登录后重试');
        return false;
    }
    // Beta/legacy CookieStore merges the domain session-memory overlay after
    // persisted cookies. setCookie alone cannot replace a stale logged-in user.
    // Public cache methods clear only this verified fixed-domain overlay. Do
    // not call CookieStore.removeCookie: it also erases the WebView session.
    var before=fqAccountCookieText(cookieHost),key=FQ_ACCOUNT_DOMAIN+'_session_cookie';
    var overlay=null,canRestoreOverlay=false,changedStore=false,cleared=false;
    try {
        if(store&&typeof store.getFromMemory==='function'&&typeof store.deleteMemory==='function'&&typeof store.putMemory==='function') {
            overlay=store.getFromMemory(key);canRestoreOverlay=true;
        }
        cookieHost.setCookie(FQ_ACCOUNT_SITE,webText);changedStore=true;
        if(canRestoreOverlay){store.deleteMemory(key);cleared=true;}
        if(fqAccountAuthSignature(fqAccountCookieText(cookieHost))!==fqAccountAuthSignature(webText))throw new Error('会话回读不一致');
        return true;
    } catch(ignore) {
        if(changedStore)try {
            cookieHost.setCookie(FQ_ACCOUNT_SITE,before);
            if(cleared){store.deleteMemory(key);if(overlay!=null)store.putMemory(key,overlay);}
            if(fqAccountAuthSignature(fqAccountCookieText(cookieHost))!==fqAccountAuthSignature(before))throw new Error('恢复失败');
        }catch(restoreError){throw new Error('官网会话同步失败，原有记录未能恢复，请重新网页登录');}
        throw new Error('本机网页会话尚未同步一致，请重新检查登录状态');
    }
}

function fqAccountVerify(src,host,cookieHost) {
    var cookieText,signature;
    try {cookieText=fqAccountCookieText(cookieHost);signature=fqAccountAuthSignature(cookieText);}
    catch(ignore){return fqAccountFinish(src,host,'unknown','','无法读取本机登录状态，请重新打开网页登录');}
    if(!signature)return fqAccountFinish(src,host,'signed-out','','尚未登录，请先完成网页登录');
    try {
        if(!host||typeof host.connect!=='function')throw new Error('客户端未提供账号检查接口');
        // Use the actual website cookie set, including secure/session variants;
        // this request is fixed to the official origin. Never persist headers.
        var url=FQ_ACCOUNT_INFO+','+JSON.stringify({method:'GET',headers:{Referer:FQ_ACCOUNT_SITE,Cookie:cookieText},retry:0});
        var response=host.connect(url);
        if(!response||typeof response.code!=='function'||typeof response.body!=='function')throw new Error('无法判断账号检查结果');
        if(fqAccountAuthSignature(fqAccountCookieText(cookieHost))!==signature)return fqAccountFinish(src,host,'unknown','','登录会话已变化，请再次检查登录状态');
        var code=Number(response.code());
        if(code===401)return fqAccountFinish(src,host,'signed-out','','登录已失效，请重新登录');
        if(code<200||code>=300)throw new Error('账号检查暂不可用');
        var root=fqParseJson(String(response.body()),false),data=root&&root.data;
        if(root&&String(root.code)==='-1'&&/请先登录|未登录|登录已失效/.test(String(root.message||'')))return fqAccountFinish(src,host,'signed-out','','登录已失效，请重新登录');
        if(!root||String(root.code)!=='0'||!data||Array.isArray(data))throw new Error('账号信息暂不可用');
        // The current official reader uses name || ('用户' + id). A real
        // verified account may not have a nickname; it is not a logged-out
        // response merely because name is empty. Do not infer reading rights.
        var displayName=typeof data.name==='string'?data.name.trim():'';
        var accountId=typeof data.id==='string'||typeof data.id==='number'?String(data.id):'';
        if(!displayName&&/^[1-9][0-9]{0,39}$/.test(accountId))displayName='用户'+accountId;
        var state=fqAccountDisplay('signed-in',displayName);
        if(state.status!=='signed-in')throw new Error('账号信息暂不可用');
        return fqAccountFinish(src,host,'signed-in',state.name,'已验证番茄账号：'+state.name);
    }catch(ignore){return fqAccountFinish(src,host,'unknown','','暂时无法检查账号，可能是网络或官网验证，请稍后重试');}
}

function fqAccountCheck(src,host,cookieHost,store) {
    try{
        // NG's browser is shared while the source cookie jar is scoped. An
        // explicit local logout must not be undone by this refresh action.
        if(cookieHost&&typeof cookieHost.captureFromWebView==='function'&&fqAccountValues(src).accountWebSyncSuppressed===true) {
            return fqAccountFinish(src,host,'signed-out','','本源登录已清除，请点“网页登录”重新启用');
        }
        fqAccountSync(cookieHost,store,false);
    }
    catch(ignore){return fqAccountFinish(src,host,'unknown','','官网会话同步失败，请重新检查登录状态或网页登录');}
    return fqAccountVerify(src,host,cookieHost);
}

function fqAccountSuppressBrowserSync(src,suppress) {
    var values=fqAccountValues(src);
    if(suppress)values.accountWebSyncSuppressed=true;
    else delete values.accountWebSyncSuppressed;
    src.putVariable(JSON.stringify(values));
}

function fqAccountLogin(src,host,cookieHost,store) {
    try {
        if(!host||typeof host.startBrowserAwait!=='function')throw new Error('客户端未提供登录窗口');
        // All audited branches offer this overload. Returning the current DOM
        // avoids a pre-sync HTTP refetch with a stale app-side cookie store.
        var loginUrl=FQ_ORIGIN+'/main/writer/login?_login_data='+encodeURIComponent(JSON.stringify({needRedirect:true,redirectURLs:{login:FQ_ACCOUNT_SITE}}));
        host.startBrowserAwait(loginUrl,'番茄网页登录',false);
    }catch(ignore){return fqAccountFinish(src,host,'unknown','','未完成网页登录，账号状态尚未验证');}
    try{
        fqAccountSync(cookieHost,store,true);
        // Only an explicitly completed login with a captured browser session
        // may undo local logout. Cancellation keeps suppression in place.
        fqAccountSuppressBrowserSync(src,false);
    }
    catch(ignore){return fqAccountFinish(src,host,'unknown','','官网会话同步失败，请重新检查登录状态或网页登录');}
